\label{mainthm:A}
\begin{enumerate}
\item For every $k\in\N$ there exists a finitely generated torsion
  group $K_k$ with growth
  \[v_{K_k}\sim\exp(n^{1-(1-\alpha)^k}).
  \]
\item For every $k\in\N$ there exists a finitely generated
  torsion-free group $H_k$ with growth
  \[v_{H_k}\sim\exp(\log(n)n^{1-(1-\alpha)^k}).\]
\end{enumerate}

