\begin{corollary}
  The groups $K_k$ from Theorem~\ref{thm:K} and $L_k$ from
  Theorem~\ref{thm:L} are finitely L-presented.\qed

\begin{proof}
  Define $K=C/(2-\eta)$ and $M=C/(1-\eta)$. We will prove, in
  fact, $\Delta(n)\le L(n-K)^\alpha$ for some constant $L$ and all $n$
  large enough.

  For that purpose, let $L$ be large enough so that $\Delta(n)\le
  L(n-K)^\alpha$ for all $n\le M$. Set $N=K/(1-\alpha)$, define
  $\Delta^*$ by
  \begin{equation}\label{eq:Delta}
    \Delta^*(n)=\begin{cases} L(n-K)^\alpha & \text{ if }n\ge N,\\
      1+(L(N-K)^\alpha-1)n/N & \text{ if }n\le N,\end{cases}
  \end{equation}
  and note that $\Delta^*$ is the convex hull of $1$ and
  $L(n-K)^\alpha$; it is a monotone concave function satisfying
  $\Delta(n)\le\Delta^*(n)$ for all $n\le M$.

  Consider now $n>M$. We then have $\ell,m<n$. By induction, we have
  $\Delta(\ell)\le\Delta^*(\ell)$ and $\Delta(m)\le\Delta^*(m)$; so,
  using concavity of $\Delta^*$,
  \begin{align*}
    \Delta(n) &\le\Delta^*(\ell)+\Delta^*(m)\le 2\Delta^*\Big(\frac12(\ell+m)\Big)\le2\Delta^*\Big(\frac\eta2\big(n+\tfrac C\eta\big)\Big)\\
    &=2L\Big(\frac\eta2\big(n+\tfrac C\eta\big)-K\Big)^\alpha
    =2L\Big(\frac\eta2(n-K)\Big)^\alpha=L(n-K)^\alpha=\Delta^*(n).
  \end{align*}
  Therefore, $\Delta(n)\le\Delta^*(n)\sim(n-K)^\alpha$ for all $n\in\N$.
\end{proof}

