  \path (16,0) edge[densely dotted] (17,0);
  \end{tikzpicture}
  \end{center}
  \caption{The Schreier graph of $\Grig$. The leftmost point is the ray $\rho=\mathsf{111}\dots$, followed by $\mathsf0\rho,\mathsf{00}\rho,\mathsf{10}\rho,\dots$}\label{fig:schreier}
